/**
 * 从请求中提取 IP 地址
 */
export function getClientIP(request: Request): string {
  // 从 headers 中获取 IP
  const forwardedFor = request.headers.get('x-forwarded-for')
  if (forwardedFor) {
    // x-forwarded-for 可能包含多个 IP，取第一个
    const ips = forwardedFor.split(',').map(ip => ip.trim())
    return ips[0]
  }

  const realIP = request.headers.get('x-real-ip')
  if (realIP) {
    return realIP
  }

  const cfConnectingIP = request.headers.get('cf-connecting-ip')
  if (cfConnectingIP) {
    return cfConnectingIP
  }

  // Next.js API 路由中可能有其他 header
  // 这里返回默认值，实际应用中需要根据部署环境调整
  return 'unknown'
}

/**
 * 生成限流键
 */
export function generateRateLimitKey(
  request: Request,
  keyGenerator?: (request: Request) => string
): string {
  if (keyGenerator) {
    return keyGenerator(request)
  }

  const ip = getClientIP(request)
  const url = new URL(request.url)
  const pathname = url.pathname

  return `${ip}:${pathname}`
}

/**
 * 格式化限流响应头
 */
export function formatRateLimitHeaders(result: RateLimitResult): Headers {
  const headers = new Headers()

  headers.set('X-RateLimit-Limit', result.limit.toString())
  headers.set('X-RateLimit-Remaining', result.remaining.toString())
  headers.set('X-RateLimit-Reset', Math.ceil(result.resetTime / 1000).toString())
  headers.set('Retry-After', result.resetAfter.toString())

  return headers
}

/**
 * Rate Limiting Configuration
 *
 * 速率限制配置定义
 */

export interface RateLimitConfig {
  /**
   * 时间窗口（毫秒）
   */
  windowMs: number

  /**
   * 时间窗口内最大请求数
   */
  maxRequests: number

  /**
   * 是否跳过成功请求（只统计失败的请求）
   */
  skipSuccessfulRequests?: boolean

  /**
   * 是否跳过失败请求
   */
  skipFailedRequests?: boolean

  /**
   * 自定义键生成器（用于根据请求生成唯一标识）
   */
  keyGenerator?: (request: Request) => string

  /**
   * 自定义跳过函数（用于判断是否跳过限流）
   */
  skip?: (request: Request) => boolean

  /**
   * 是否使用 Redis（分布式部署时启用）
   */
  useRedis?: boolean

  /**
   * Redis 配置（当 useRedis=true 时需要）
   */
  redisConfig?: {
    host?: string
    port?: number
    password?: string
    url?: string
    db?: number
  }
}

