import { v4 as uuidv4 } from 'uuid'
import {
  PerformanceMetric,
  APIMetric,
  ErrorMetric,
  OperationMetric,
  AggregatedMetrics,
  AlarmEvent,
  MonitoringConfig,
} from './types'
import { getMonitoringConfig } from './config'
import { MonitoringStorage, MemoryStorage, LocalStorageStorage } from './storage'

export class PerformanceMonitor {
  private static instance: PerformanceMonitor
  private config: MonitoringConfig
  private storage: MonitoringStorage
  private activeOperations: Map<string, { startTime: number; name: string }> = new Map()

  private constructor() {
    this.config = getMonitoringConfig()
    this.storage = this.createStorage()
  }

  static getInstance(): PerformanceMonitor {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor()
    }
    return PerformanceMonitor.instance
  }

  private createStorage(): MonitoringStorage {
    switch (this.config.storageType) {
      case 'localStorage':
        return new LocalStorageStorage(this.config.retentionPeriodMs)
      case 'memory':
      default:
        return new MemoryStorage(this.config.retentionPeriodMs)
    }
  }

  private shouldSample(): boolean {
    if (!this.config.enabled) return false
    return Math.random() < this.config.sampleRate
  }

  /**
   * Track API request performance
   * 追踪 API 请求性能
   */
  async trackAPIRequest(
    method: APIMetric['method'],
    endpoint: string,
    statusCode: number,
    responseTime: number,
    metadata?: Record<string, any>
  ): Promise<void> {
    if (!this.shouldSample()) return

    const metric: APIMetric = {
      id: uuidv4(),
      name: `API ${method} ${endpoint}`,
      timestamp: Date.now(),
      type: 'api',
      method,
      endpoint,
      statusCode,
      responseTime,
      success: statusCode >= 200 && statusCode < 300,
      value: responseTime,
      unit: 'ms',
      metadata,
    }

    await this.storage.saveMetric(metric)

    // 检查是否触发告警
    if (this.config.alarms.responseTime.enabled) {
      await this.checkResponseTimeAlarm()
    }
    if (this.config.alarms.errorRate.enabled) {
      await this.checkErrorRateAlarm()
    }
  }

  /**
   * Track error
   * 追踪错误
   */
  async trackError(
    errorType: string,
    errorMessage: string,
    stackTrace?: string,
    context?: Record<string, any>
  ): Promise<void> {
    if (!this.shouldSample()) return

    const metric: ErrorMetric = {
      id: uuidv4(),
      name: `Error: ${errorType}`,
      timestamp: Date.now(),
      type: 'error',
      errorType,
      errorMessage,
      stackTrace,
      context,
      value: 1,
      unit: 'count',
    }

    await this.storage.saveMetric(metric)

    // 检查是否触发错误率告警
    if (this.config.alarms.errorRate.enabled) {
      await this.checkErrorRateAlarm()
    }
  }

  /**
   * Start tracking an operation
   * 开始追踪操作
   */
  startOperation(operationName: string): string {
    const operationId = uuidv4()
    this.activeOperations.set(operationId, {
      startTime: Date.now(),
      name: operationName,
    })
    return operationId
  }

  /**
   * End tracking an operation
   * 结束追踪操作
   */
  async endOperation(
    operationId: string,
    success: boolean = true,
    metadata?: Record<string, any>
  ): Promise<void> {
    const operation = this.activeOperations.get(operationId)
    if (!operation) return

    const duration = Date.now() - operation.startTime
    this.activeOperations.delete(operationId)

    if (!this.shouldSample()) return

    const metric: OperationMetric = {
      id: uuidv4(),
      name: operation.name,
      timestamp: Date.now(),
      type: 'operation',
      operationName: operation.name,
      duration,
      success,
      value: duration,
      unit: 'ms',
      metadata,
    }

    await this.storage.saveMetric(metric)

    // 检查是否触发操作时长告警
    if (this.config.alarms.operationDuration.enabled) {
      await this.checkOperationDurationAlarm()
    }
  }

  /**
   * Track custom metric
   * 追踪自定义指标
   */
  async trackCustomMetric(
    name: string,
    value: number,
    unit: string,
    metadata?: Record<string, any>
  ): Promise<void> {
    if (!this.shouldSample()) return

    const metric: PerformanceMetric = {
      id: uuidv4(),
      name,
      timestamp: Date.now(),
      type: 'custom',
      value,
      unit,
      metadata,
    }

    await this.storage.saveMetric(metric)
  }

  /**
   * Get aggregated metrics
   * 获取聚合指标
   */
  async getAggregatedMetrics(timeWindowMs: number = 5 * 60 * 1000): Promise<AggregatedMetrics> {
    const endTime = Date.now()
