      return await this.executeTool(name, args)
    } catch (error) {
      return {
        content: [
          {
            type: 'text',
            text: `Error executing tool "${name}": ${error}`,
          },
        ],
        isError: true,
      }
    }
  }

  /**
   * 执行工具（实际实现）
   */
  private async executeTool(name: string, args: Record<string, unknown>): Promise<ToolResult> {
    // 使用真实的工具执行器
    return await ToolExecutor.execute(name, args)
  }

  /**
   * 处理 JSON-RPC 请求
   */
  async handleRequest(request: MCPRequest |

(request: MCPRequest): Promise<MCPResponse> {
    try {
      switch (request.method) {
        case 'tools/list':
          return {
            jsonrpc: '2.0',
            id: request.id,
            result: await this.listTools(),
          }

        case 'tools/call':
          if (!request.params?.name || typeof request.params.name !== 'string') {
            return {
              jsonrpc: '2.0',
              id: request.id,
              error: {
                code: -32602,
                message: 'Invalid params: name is required',
              },
            }
          }
          return {
            jsonrpc: '2.0',
            id: request.id,
            result: await this.callTool(
              request.params.name as string,
              (request.params.arguments || {}) as Record<string, unknown>
            ),
          }

        default:
          return {
            jsonrpc: '2.0',
            id: request.id,
            error: {
              code: -32601,
              message: `Method not found: ${request.method}`,
            },
          }
      }
    } catch (error) {
      return {
        jsonrpc: '2.0',
        id: request.id,
        error: {
          code: -32603,
          message: `Internal error: ${error}`,
        },
      }
    }
  }
}

