  const draft = value as Draft<T>

  return (
    typeof draft.id === 'string' &&
    typeof draft.type === 'string' &&
    typeof draft.createdAt === 'number' &&
    typeof draft.updatedAt === 'number' &&
    typeof draft.expiresAt === 'number' &&
    'data' in draft
  )
