/**
 * 模板选择器主组件
 */
export function TemplateSelector({
  onSelectTemplate,
  onCancel,
  className = '',
}: TemplateSelectorProps): React.ReactElement {
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('all')
  const [searchQuery, setSearchQuery] = useState('')

  // 筛选模板
  const filteredTemplates = useMemo(() => {
    let templates = listTemplates()

    // 按类别筛选
    if (selectedCategory !== 'all') {
      templates = listTemplatesByCategory(selectedCategory as WorkflowTemplate['category'])
    }

    // 按难度筛选
    if (selectedDifficulty !== 'all') {
      templates = templates.filter((t) => t.difficulty === selectedDifficulty)
    }

    // 按搜索词筛选
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase()
      templates = templates.filter(
        (t) =>
          t.name.toLowerCase().includes(query) ||
          t.description.toLowerCase().includes(query) ||
          t.tags.some((tag) => tag.toLowerCase().includes(query))
      )
    }

    return templates
  }, [selectedCategory, selectedDifficulty, searchQuery])

  return (
    <div style={styles.container} className={className}>
      <div style={styles.header}>
        <h2 style={styles.title}>选择工作流模板</h2>
        {onCancel && (
          <button
            style={{
              padding: '6px 12px',
              border: '1px solid #dee2e6',
              borderRadius: '4px',
              backgroundColor: '#ffffff',
              cursor: 'pointer',
            }}
            onClick={onCancel}
          >
            取消
          </button>
        )}
      </div>

      {/* 搜索框 */}
      <div>
        <input
          type="text"
          placeholder="搜索模板..."
          style={styles.searchInput}
          value={searchQuery

}>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'all' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('all')}
        >
          全部
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'basic' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('basic')}
        >
          基础
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'ai' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('ai')}
        >
          AI
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'data' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('data')}
        >
          数据
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'logic' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('logic')}
        >
          逻辑
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedCategory === 'advanced' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedCategory('advanced')}
        >
          高级
        </button>
      </div>

      {/* 难度筛选 */}
      <div style={styles.filters}>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedDifficulty === 'all' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedDifficulty('all')}
        >
          全部难度
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedDifficulty === 'beginner' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedDifficulty('beginner')}
        >
          入门
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedDifficulty === 'intermediate' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedDifficulty('intermediate')}
        >
          中级
        </button>
        <button
          style={{
            ...styles.filterButton,
            ...(selectedDifficulty === 'advanced' ? styles.filterButtonActive : {}),
          }}
          onClick={() => setSelectedDifficulty('advanced')}
        >
          高级
        </button>
      </div>

      {/* 模板网格 */}
      {filteredTemplates.length > 0 ? (
        <div style={styles.grid}>
          {filteredTemplates.map((template) => (
            <TemplateCard
              key={template.id}
              template={template}
              onSelect={onSelectTemplate}
            />
          ))}
        </div>
      ) : (
        <div style={styles.empty}>
          <p>没有找到匹配的模板</p>
          <p style={{ fontSize: '14px', marginTop: '8px' }}>
            尝试调整筛选条件或搜索关键词
          </p>
        </div>
      )}
    </div>
  )
}

