export function createSession(userId: string, expiresInMinutes = 60): Session {
  const now = new Date()
  const expiresAt = new Date(now.getTime() + expiresInMinutes * 60 * 1000)

  return {
    token: generateToken(),
    userId,
    expiresAt,
    createdAt: now,
  }
}

